import type { jsPDF } from "jspdf";
import type { Language } from "./db";

/**
 * The embedded font is a mechanical merge of Noto Sans Devanagari Regular and
 * Noto Sans Bengali Regular. Both source fonts are distributed under the SIL
 * Open Font License 1.1. Keeping the data in this module makes PDF creation
 * fully offline in the web app, Android WebView, Tauri, and Node-based tests.
 *
 * Source packages:
 * - @expo-google-fonts/noto-sans-devanagari 0.4.1
 * - @expo-google-fonts/noto-sans-bengali 0.4.1
 * Copyright notices and the complete license are in Noto-Indic-OFL.txt.
 */
const INDIC_FONT_BASE64 = "";
const INDIC_FONT_FILE = "Midori-Noto-Indic-Regular.ttf";
const INDIC_FONT_FAMILY = "MidoriNotoIndic";
/** HarfBuzz WASM is vendored from harfbuzzjs 1.6.0; see HarfBuzz-LICENSE.txt. */
const INDIC_SHAPER_WASM_BASE64 = "";

export type PdfLanguage = Language;
export type PdfFontStyle = "normal" | "bold";

export const normalizePdfLanguage = (language?: Language): Language =>
  language === "hi" || language === "bn" ? language : "en";

export const pdfLocale = (language?: Language) =>
  normalizePdfLanguage(language) === "hi"
    ? "hi-IN"
    : normalizePdfLanguage(language) === "bn"
      ? "bn-IN"
      : "en-IN";

/** Modern Indian business displays keep Latin digits while localizing words. */
export const pdfNumber = (value: number, language: Language = "en") =>
  new Intl.NumberFormat(pdfLocale(language), {
    numberingSystem: "latn",
    maximumFractionDigits: 2,
  }).format(Number.isFinite(value) ? value : 0);

export const pdfMoney = (
  value: number,
  language: Language = "en",
  minimumFractionDigits = 2,
) =>
  `Rs. ${new Intl.NumberFormat(pdfLocale(language), {
    numberingSystem: "latn",
    minimumFractionDigits,
    maximumFractionDigits: 2,
  }).format(Number.isFinite(value) ? value : 0)}`;

export const pdfDate = (
  value: string | Date,
  language: Language = "en",
  options: Intl.DateTimeFormatOptions = {
    day: "2-digit",
    month: "short",
    year: "numeric",
  },
) => {
  const date = value instanceof Date ? value : new Date(`${value}T00:00:00`);
  return new Intl.DateTimeFormat(pdfLocale(language), {
    numberingSystem: "latn",
    ...options,
  }).format(date);
};

export const pdfDateTime = (
  value: string | Date,
  language: Language = "en",
) => {
  const date = value instanceof Date ? value : new Date(value);
  return new Intl.DateTimeFormat(pdfLocale(language), {
    numberingSystem: "latn",
    day: "2-digit",
    month: "short",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  }).format(date);
};

