type PdfPathOperation = { op: "m" | "l" | "c" | "h"; c: number[] };

const INDIC_TEXT = /[\u0900-\u097f\u0980-\u09ff]/u;
const SCRIPT_RUNS = /[\u0900-\u097f\u200c\u200d]+|[\u0980-\u09ff\u200c\u200d]+|[^\u0900-\u09ff]+/gu;
const patchedDocuments = new WeakSet<jsPDF>();

function base64Bytes(value: string) {
  const binary = atob(value);
  const result = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) result[index] = binary.charCodeAt(index);
  return result;
}

type NumericWasmFunction = (...args: number[]) => number;

function encodeWasmVector(values: number[]) {
  const length = values.length;
  return [length % 128 | 128, length >> 7, ...values];
}

function wrapTableCallback(callback: (...args: number[]) => void, signature: string) {
  const typeCodes: Record<string, number> = {
    i: 0x7f, p: 0x7f, j: 0x7e, f: 0x7d, d: 0x7c, e: 0x6f,
  };
  const encodeTypes = (types: string) =>
    encodeWasmVector([...types].map((type) => typeCodes[type]));
  const parameters = encodeTypes(signature.slice(1));
  const result = encodeTypes(signature[0] === "v" ? "" : signature[0]);
  const bytes = Uint8Array.of(
    0x00, 0x61, 0x73, 0x6d, 0x01, 0x00, 0x00, 0x00,
    0x01, ...encodeWasmVector([0x01, 0x60, ...parameters, ...result]),
    0x02, 0x07, 0x01, 0x01, 0x65, 0x01, 0x66, 0x00, 0x00,
    0x07, 0x05, 0x01, 0x01, 0x66, 0x00, 0x00,
  );
  const wrapper = new WebAssembly.Instance(
    new WebAssembly.Module(bytes),
    { e: { f: callback } },
  ).exports.f;
  if (typeof wrapper !== "function") throw new Error("Could not wrap HarfBuzz callback.");
  return wrapper;
}

/**
 * Minimal Emscripten bootstrap for the embedded HarfBuzz binary. The upstream
 * generated loader resolves a sibling WASM file at build time, which makes
 * Vite emit an unused external asset. This bootstrap exposes only the
 * functions needed by the PDF shaper and never reads or fetches a second file.
 */
async function createEmbeddedHarfBuzz(): Promise<RawHarfBuzz> {
  const runtime: {
    memory?: WebAssembly.Memory;
    wasmExports?: WebAssembly.Exports;
    moduleView?: RawHarfBuzz;
  } = {};
  let heapU8 = new Uint8Array();
  let heapU16 = new Uint16Array();
  let heapU32 = new Uint32Array();
  let heap32 = new Int32Array();
  const timers = new Map<number, ReturnType<typeof setTimeout>>();

  const refreshMemoryViews = () => {
    if (!runtime.memory) return;
    heapU8 = new Uint8Array(runtime.memory.buffer);
    heapU16 = new Uint16Array(runtime.memory.buffer);
    heapU32 = new Uint32Array(runtime.memory.buffer);
    heap32 = new Int32Array(runtime.memory.buffer);
    if (runtime.moduleView) {
      runtime.moduleView.HEAPU8 = heapU8;
      runtime.moduleView.HEAPU16 = heapU16;
      runtime.moduleView.HEAPU32 = heapU32;
      runtime.moduleView.HEAP32 = heap32;
    }
  };

  const resizeHeap = (requestedSize: number) => {
    if (!runtime.memory) return 0;
    const currentSize = runtime.memory.buffer.byteLength;
    const requested = requestedSize >>> 0;
    if (requested <= currentSize) return 1;
    const maximum = 2_147_483_648;
    const desired = Math.min(
      maximum,
      Math.max(requested, currentSize + Math.ceil(currentSize * 0.2)),
    );
    try {
      runtime.memory.grow(Math.ceil((desired - currentSize) / 65_536));
      refreshMemoryViews();
      return 1;
    } catch {
      return 0;
    }
  };

  const imports: WebAssembly.Imports = {
    env: {
      _abort_js: () => { throw new WebAssembly.RuntimeError("HarfBuzz aborted."); },
      _emscripten_runtime_keepalive_clear: () => undefined,
      _setitimer_js: (which: number, timeoutMs: number) => {
        const previous = timers.get(which);
        if (previous) clearTimeout(previous);
        timers.delete(which);
        if (timeoutMs <= 0) return 0;
        const timer = setTimeout(() => {
          timers.delete(which);
          const timeout = runtime.wasmExports?.emscripten_timeout;
          if (typeof timeout === "function") {
            (timeout as NumericWasmFunction)(which, performance.now());
          }
        }, timeoutMs);
        timers.set(which, timer);
        return 0;
      },
      emscripten_resize_heap: resizeHeap,
    },
    wasi_snapshot_preview1: {
      proc_exit: (status: number) => {
        throw new WebAssembly.RuntimeError(`HarfBuzz exited with status ${status}.`);
      },
    },
  };

  const { instance } = await WebAssembly.instantiate(
    base64Bytes(INDIC_SHAPER_WASM_BASE64),
    imports,
  );
  runtime.wasmExports = instance.exports;
  if (!(runtime.wasmExports.memory instanceof WebAssembly.Memory)) {
    throw new Error("Embedded HarfBuzz did not export memory.");
  }
  if (!(runtime.wasmExports.__indirect_function_table instanceof WebAssembly.Table)) {
    throw new Error("Embedded HarfBuzz did not export its callback table.");
  }
  runtime.memory = runtime.wasmExports.memory;
  refreshMemoryViews();
  const table = runtime.wasmExports.__indirect_function_table;
  const wasmFunction = (name: string) => {
    const value = runtime.wasmExports?.[name];
    if (typeof value !== "function") throw new Error(`Missing HarfBuzz export: ${name}`);
    return value as NumericWasmFunction;
  };
  const addFunction = (callback: (...args: number[]) => void, signature: string) => {
    const index = table.grow(1);
    table.set(index, wrapTableCallback(callback, signature));
    return index;
  };

  runtime.moduleView = {
    HEAPU8: heapU8,
    HEAPU16: heapU16,
    HEAPU32: heapU32,
    HEAP32: heap32,
    _malloc: wasmFunction("malloc"),
    _free: wasmFunction("free"),
    addFunction,
    _hb_blob_create: wasmFunction("hb_blob_create"),
    _hb_face_create: wasmFunction("hb_face_create"),
    _hb_face_get_upem: wasmFunction("hb_face_get_upem"),
    _hb_font_create: wasmFunction("hb_font_create"),
    _hb_font_set_scale: wasmFunction("hb_font_set_scale"),
    _hb_buffer_create: wasmFunction("hb_buffer_create"),
    _hb_buffer_destroy: wasmFunction("hb_buffer_destroy"),
    _hb_buffer_add_utf16: wasmFunction("hb_buffer_add_utf16"),
    _hb_buffer_guess_segment_properties: wasmFunction("hb_buffer_guess_segment_properties"),
    _hb_buffer_get_length: wasmFunction("hb_buffer_get_length"),
    _hb_buffer_get_glyph_infos: wasmFunction("hb_buffer_get_glyph_infos"),
    _hb_buffer_get_glyph_positions: wasmFunction("hb_buffer_get_glyph_positions"),
    _hb_shape: wasmFunction("hb_shape"),
    _hb_draw_funcs_create: wasmFunction("hb_draw_funcs_create"),
    _hb_draw_funcs_set_move_to_func: wasmFunction("hb_draw_funcs_set_move_to_func"),
    _hb_draw_funcs_set_line_to_func: wasmFunction("hb_draw_funcs_set_line_to_func"),
    _hb_draw_funcs_set_quadratic_to_func: wasmFunction("hb_draw_funcs_set_quadratic_to_func"),
    _hb_draw_funcs_set_cubic_to_func: wasmFunction("hb_draw_funcs_set_cubic_to_func"),
    _hb_draw_funcs_set_close_path_func: wasmFunction("hb_draw_funcs_set_close_path_func"),
    _hb_font_draw_glyph: wasmFunction("hb_font_draw_glyph"),
  };
  wasmFunction("__wasm_call_ctors")();
  return runtime.moduleView;
}

let shaperPromise: Promise<IndicShaper> | undefined;

function getIndicShaper() {
  return shaperPromise ??= (async () => {
  const hbModule = await createEmbeddedHarfBuzz();
  const fontData = base64Bytes(INDIC_FONT_BASE64);
  const fontDataPointer = hbModule._malloc(fontData.byteLength);
  hbModule.HEAPU8.set(fontData, fontDataPointer);
  // The font buffer stays alive for the lifetime of the app/PDF worker.
  const blob = hbModule._hb_blob_create(fontDataPointer, fontData.byteLength, 2, 0, 0);
  const face = hbModule._hb_face_create(blob, 0);
  const unitsPerEm = hbModule._hb_face_get_upem(face);
  const font = hbModule._hb_font_create(face);
  hbModule._hb_font_set_scale(font, unitsPerEm, unitsPerEm);

  let activeCommands: GlyphCommand[] | undefined;
  const drawFunctions = hbModule._hb_draw_funcs_create();
  const moveTo = hbModule.addFunction((...args) => {
    activeCommands?.push({ type: "M", values: [args[3], args[4]] });
  }, "viiiffi");
  const lineTo = hbModule.addFunction((...args) => {
    activeCommands?.push({ type: "L", values: [args[3], args[4]] });
  }, "viiiffi");
  const quadraticTo = hbModule.addFunction((...args) => {
    activeCommands?.push({ type: "Q", values: [args[3], args[4], args[5], args[6]] });
  }, "viiiffffi");
  const cubicTo = hbModule.addFunction((...args) => {
    activeCommands?.push({
      type: "C",
      values: [args[3], args[4], args[5], args[6], args[7], args[8]],
    });
  }, "viiiffffffi");
  const closePath = hbModule.addFunction(() => {
    activeCommands?.push({ type: "Z", values: [] });
  }, "viiii");
  hbModule._hb_draw_funcs_set_move_to_func(drawFunctions, moveTo, 0, 0);
  hbModule._hb_draw_funcs_set_line_to_func(drawFunctions, lineTo, 0, 0);
  hbModule._hb_draw_funcs_set_quadratic_to_func(drawFunctions, quadraticTo, 0, 0);
  hbModule._hb_draw_funcs_set_cubic_to_func(drawFunctions, cubicTo, 0, 0);
  hbModule._hb_draw_funcs_set_close_path_func(drawFunctions, closePath, 0, 0);

  const pathCache = new Map<number, GlyphCommand[]>();
  return {
    unitsPerEm,
    shape(text: string) {
      const textPointer = hbModule._malloc(text.length * 2);
      const textWords = hbModule.HEAPU16.subarray(textPointer / 2, textPointer / 2 + text.length);
      for (let index = 0; index < text.length; index += 1) textWords[index] = text.charCodeAt(index);
      const buffer = hbModule._hb_buffer_create();
      try {
        hbModule._hb_buffer_add_utf16(buffer, textPointer, text.length, 0, text.length);
        hbModule._hb_buffer_guess_segment_properties(buffer);
        hbModule._hb_shape(font, buffer, 0, 0);
        const count = hbModule._hb_buffer_get_length(buffer);
        const infoStart = hbModule._hb_buffer_get_glyph_infos(buffer, 0) / 4;
        const positionStart = hbModule._hb_buffer_get_glyph_positions(buffer, 0) / 4;
        const glyphs: ShapedGlyph[] = [];
        let advance = 0;
        for (let index = 0; index < count; index += 1) {
          const info = infoStart + index * 5;
          const position = positionStart + index * 5;
          const glyph: ShapedGlyph = {
            glyphId: hbModule.HEAPU32[info],
            xAdvance: hbModule.HEAP32[position],
            yAdvance: hbModule.HEAP32[position + 1],
            xOffset: hbModule.HEAP32[position + 2],
            yOffset: hbModule.HEAP32[position + 3],
          };
          glyphs.push(glyph);
          advance += glyph.xAdvance;
        }
        return { glyphs, advance };
      } finally {
        hbModule._hb_buffer_destroy(buffer);
        hbModule._free(textPointer);
      }
    },
    glyphPath(glyphId: number) {
      const cached = pathCache.get(glyphId);
      if (cached) return cached;
      activeCommands = [];
      hbModule._hb_font_draw_glyph(font, glyphId, drawFunctions, 0);
      const commands = activeCommands;
      activeCommands = undefined;
      pathCache.set(glyphId, commands);
      return commands;
    },
  };
  })();
}

function shapeLine(shaper: IndicShaper, text: string) {
  const glyphs: ShapedGlyph[] = [];
  let advance = 0;
  for (const run of text.match(SCRIPT_RUNS) || [text]) {
    const shaped = shaper.shape(run);
    glyphs.push(...shaped.glyphs);
    advance += shaped.advance;
  }
  return { glyphs, advance };
}

function pathPoint(
  originX: number,
  originY: number,
  scaleX: number,
  scaleY: number,
  x: number,
  y: number,
) {
  return [originX + x * scaleX, originY - y * scaleY];
}

function drawShapedLine(
  doc: jsPDF,
  shaper: IndicShaper,
  text: string,
  x: number,
  y: number,
  options: PdfTextOptions,
) {
  const shaped = shapeLine(shaper, text);
  const unitScale = doc.getFontSize() / doc.internal.scaleFactor / shaper.unitsPerEm;
  const requestedScale = typeof options.horizontalScale === "number" ? options.horizontalScale : 1;
  const naturalWidth = shaped.advance * unitScale * requestedScale;
  const fitScale = typeof options.maxWidth === "number" && options.maxWidth > 0 && naturalWidth > options.maxWidth
    ? options.maxWidth / naturalWidth
    : 1;
  const scaleX = unitScale * requestedScale * fitScale;
  const scaleY = unitScale;
  const width = shaped.advance * scaleX;
  const startX = options.align === "right"
    ? x - width
    : options.align === "center"
      ? x - width / 2
      : x;
  const operations: PdfPathOperation[] = [];
  let penX = 0;
  let penY = 0;
  for (const glyph of shaped.glyphs) {
    const originX = startX + (penX + glyph.xOffset) * scaleX;
    const originY = y - (penY + glyph.yOffset) * scaleY;
    let current = [originX, originY];
    for (const command of shaper.glyphPath(glyph.glyphId)) {
      if (command.type === "M" || command.type === "L") {
        const point = pathPoint(originX, originY, scaleX, scaleY, command.values[0], command.values[1]);
        current = point;
        operations.push({ op: command.type.toLowerCase() as "m" | "l", c: point });
      } else if (command.type === "C") {
        const first = pathPoint(originX, originY, scaleX, scaleY, command.values[0], command.values[1]);
        const second = pathPoint(originX, originY, scaleX, scaleY, command.values[2], command.values[3]);
        const end = pathPoint(originX, originY, scaleX, scaleY, command.values[4], command.values[5]);
        current = end;
        operations.push({ op: "c", c: [...first, ...second, ...end] });
      } else if (command.type === "Q") {
        const control = pathPoint(originX, originY, scaleX, scaleY, command.values[0], command.values[1]);
        const end = pathPoint(originX, originY, scaleX, scaleY, command.values[2], command.values[3]);
        const first = [
          current[0] + (2 / 3) * (control[0] - current[0]),
          current[1] + (2 / 3) * (control[1] - current[1]),
        ];
        const second = [
          end[0] + (2 / 3) * (control[0] - end[0]),
          end[1] + (2 / 3) * (control[1] - end[1]),
        ];
        current = end;
        operations.push({ op: "c", c: [...first, ...second, ...end] });
      } else {
        operations.push({ op: "h", c: [] });
      }
    }
    penX += glyph.xAdvance;
    penY += glyph.yAdvance;
  }
  if (!operations.length) return;
  const fillColor = doc.getFillColor();
  doc.setFillColor(doc.getTextColor());
  doc.path(operations).fill();
  doc.setFillColor(fillColor);
}

function installIndicTextRenderer(doc: jsPDF, shaper: IndicShaper) {
  if (patchedDocuments.has(doc)) return;
  patchedDocuments.add(doc);
  const originalText = doc.text.bind(doc) as unknown as (...args: unknown[]) => jsPDF;
  Object.defineProperty(doc, "text", {
    configurable: true,
    value: (...args: unknown[]) => {
      const [text, x, y, rawOptions, transform] = args;
      const sourceLines = Array.isArray(text)
        ? text.flatMap((line) => String(line).split("\n"))
        : String(text).split("\n");
      if (
        typeof x !== "number" || typeof y !== "number"
        || !sourceLines.some((line) => INDIC_TEXT.test(line))
      ) return originalText(...args);
      const options = rawOptions && typeof rawOptions === "object"
        ? rawOptions as PdfTextOptions
        : {};
      if (options.angle != null || options.align === "justify") return originalText(...args);
      const lineHeight = doc.getFontSize()
        * (options.lineHeightFactor || doc.getLineHeightFactor())
        / doc.internal.scaleFactor;
      sourceLines.forEach((line, index) => {
        const lineY = y + index * lineHeight;
        // Keep a standards-based, searchable Unicode text layer. It is hidden
        // because jsPDF does not apply Indic GSUB/GPOS shaping on its own.
        originalText(line, x, lineY, { ...options, renderingMode: "invisible" }, transform);
        drawShapedLine(doc, shaper, line, x, lineY, options);
      });
      return doc;
    },
  });
}

/** Register the Unicode font and HarfBuzz-powered Indic shaping renderer. */
export async function registerPdfFont(doc: jsPDF) {
  const fonts = doc.getFontList();
  if (!fonts[INDIC_FONT_FAMILY]) {
    doc.addFileToVFS(INDIC_FONT_FILE, INDIC_FONT_BASE64);
    doc.addFont(INDIC_FONT_FILE, INDIC_FONT_FAMILY, "normal");
    doc.addFont(INDIC_FONT_FILE, INDIC_FONT_FAMILY, "bold");
  }
  doc.setFont(INDIC_FONT_FAMILY, "normal");
  installIndicTextRenderer(doc, await getIndicShaper());
  return doc;
}

export function setPdfFont(
  doc: jsPDF,
  style: PdfFontStyle = "normal",
) {
  doc.setFont(INDIC_FONT_FAMILY, style);
}

export function pdfPaymentMode(mode: string | undefined, language: Language = "en") {
  const active = normalizePdfLanguage(language);
  if (!mode) return "";
  const labels: Record<Language, Record<string, string>> = {
    en: { cash: "Cash", upi: "UPI", bank: "Bank", cheque: "Cheque", credit: "Credit", mixed: "Mixed" },
    hi: { cash: "नकद", upi: "UPI", bank: "बैंक", cheque: "चेक", credit: "उधार", mixed: "मिला-जुला" },
    bn: { cash: "নগদ", upi: "UPI", bank: "ব্যাংক", cheque: "চেক", credit: "বাকি", mixed: "মিশ্র" },
  };
  return labels[active][mode.toLowerCase()] || mode;
}
